"""Chapter 20 (Partnership) of Rakesh Yadav '7300+ Maths', book pp.661-662 (Q1-25).
Filed into tools/topics/partnership.py: new PYQs into the four existing qtypes, plus two
new qtypes (q-pt-find-time, q-pt-split-rule) for patterns those four don't cover.
"""
from fractions import Fraction as F
from bank import bound, mistake, opt_val, pyq, ratio_val

RY = "ry7300-ch20-partnership"
NONE = -1e18  # sentinel for a "None of these" option, never equal to a real computed value

PYQS_RY = [
    # --- q-pt-two (existing): equal time or already-known ratio, split a profit ---
    pyq(RY, 1, "q-pt-two",
        'A and B started a business by investing ₹36,000 and ₹63,000. Find the share of each, out of the annual profit of ₹5,500.',
        ['₹2000, ₹3500', '₹2500, ₹3500', '₹3500, ₹2500', 'None of these'], "a",
        ['Equal time, so the ratio is the capital ratio 36,000 : 63,000 = 4 : 7.', "A's share = 4/11 × 5,500 = ₹2,000; B's share = 7/11 × 5,500 = ₹3,500."],
        lambda: 1, 1, 0, tech=['ratio-parts'], optvals=[1, 0, 0, 0], concepts=1,
        trick='Equal time → split by the capital ratio alone.'),
    pyq(RY, 13, "q-pt-two",
        'A, B and C subscribe ₹47,000 for a business. A subscribes ₹7,000 more than B, and B ₹5,000 more than C. Out of a total profit of ₹4,700, C receives:',
        ['₹1200', '₹4500', '₹1000', 'None of these'], "c",
        ['Let C = c; then B = c + 5,000 and A = c + 12,000. Their sum is 3c + 17,000 = 47,000, so c = 10,000.', 'A = 22,000, B = 15,000, C = 10,000, giving the ratio 22 : 15 : 10 (47 parts).', "C's share = 10/47 × 4,700 = ₹1,000."],
        lambda: F(4700 * 10, 47), 1000, 0, tech=['ratio-parts'], concepts=2,
        optvals=[opt_val(o) for o in ['₹1200', '₹4500', '₹1000', 'None of these']],
        trick='Work out the three capitals from the relations first, then split the profit in that ratio.',
        ),
    pyq(RY, 15, "q-pt-two",
        'Two partners X and Y start a business by investing ₹50,000 and ₹40,000 respectively. What will be the ratio of their profits at the end of the year?',
        ['5 : 4', '3 : 6', '4 : 5', '6 : 3'], "a",
        ['Equal time, so the profit ratio is simply the capital ratio.', '50,000 : 40,000 = 5 : 4.'],
        lambda: ratio_val('5:4'), ratio_val('5:4'), 0, tech=['ratio-parts'], optvals=[ratio_val(o) for o in ['5 : 4', '3 : 6', '4 : 5', '6 : 3']],
        trick='Equal time → the profit ratio is just the capital ratio, simplified.'),
    pyq(RY, 18, "q-pt-two",
        "A and B started a business investing ₹1,85,000 and ₹2,25,000 respectively. If B's share in the profit earned by them is ₹9,000, what is the total profit earned by them together?",
        ['₹17,400', '₹16,400', '₹16,800', '₹17,800'], "b",
        ['Equal time, so the ratio is 1,85,000 : 2,25,000 = 37 : 45 (82 parts).', "B has 45 of 82 parts, so the total profit = 9,000 × 82 ÷ 45 = ₹16,400."],
        lambda: F(9000 * 82, 45), 16400, 0, tech=['ratio-parts'], concepts=1,
        trick="Find B's fraction of the whole (45/82), then total = known share ÷ that fraction."),
    pyq(RY, 19, "q-pt-two",
        "A and B started a boutique investing amounts of ₹35,000 and ₹56,000. If A's share in the profit earned by them is ₹45,000, what is the total profit earned?",
        ['₹81,000', '₹1,27,000', '₹72,000', '₹1,17,000'], "d",
        ['Equal time, so the ratio is 35,000 : 56,000 = 5 : 8 (13 parts).', "A has 5 of 13 parts, so the total profit = 45,000 × 13 ÷ 5 = ₹1,17,000."],
        lambda: F(45000 * 13, 5), 117000, 0, tech=['ratio-parts'], concepts=1,
        trick="Find A's fraction of the whole (5/13), then total = known share ÷ that fraction.",
        ),
    pyq(RY, 20, "q-pt-two",
        'A and B invested ₹40,000 and ₹75,000 respectively. At the end of five years they got a total dividend of ₹46,000. What is A’s share in the dividend?',
        ['₹16,500', '₹15,500', '₹15,000', '₹16,000'], "d",
        ['Equal time (both for the same five years), so the ratio is 40,000 : 75,000 = 8 : 15 (23 parts).', "A's share = 8/23 × 46,000 = ₹16,000."],
        lambda: F(8 * 46000, 23), 16000, 0, tech=['ratio-parts'],
        trick='A long, equal time period for both still just gives the plain capital ratio.'),

    # --- q-pt-late (existing): different joining/withdrawal times ---
    pyq(RY, 2, "q-pt-late",
        'A starts some business with ₹50,000. After 3 months B joins him with ₹70,000. At the end of the year, in what ratio should they share the profit?',
        ['1 : 3', '3 : 2', '1 : 5', 'None of these'], "d",
        ['A is in for all 12 months, B for 12 − 3 = 9 months.', 'Capital-months: A = 50,000×12 = 6,00,000; B = 70,000×9 = 6,30,000.', 'Ratio 600 : 630 = 20 : 21, which matches none of the first three options.'],
        lambda: NONE, NONE, 0, tech=['ratio-parts'], optvals=[ratio_val('1:3'), ratio_val('3:2'), ratio_val('1:5'), NONE], concepts=2,
        trick='Work out the actual capital-months ratio (20 : 21) before assuming it matches a "nice" option.'),
    pyq(RY, 3, "q-pt-late",
        'A started a business by investing ₹36,000. After 4 months B joined him with some investment. At the end of the year, the total profit was divided between them in the ratio 9 : 7. How much capital was invested by B in the business?',
        ['₹40,000', '₹42,000', '₹41,000', 'None of these'], "b",
        ["A's capital-months = 36,000×12 = 4,32,000, which is A's 9 parts of the 9 : 7 ratio.", "One part = 4,32,000 ÷ 9 = 48,000, so B's capital-months = 7 × 48,000 = 3,36,000.", 'B was in for 12 − 4 = 8 months, so his capital = 3,36,000 ÷ 8 = ₹42,000.'],
        lambda: F(36000 * 12 * 7, 9) / 8, 42000, 0, tech=['ratio-parts'], concepts=2,
        optvals=[opt_val(o) for o in ['₹40,000', '₹42,000', '₹41,000', 'None of these']],
        trick="Get B's capital-months from the ratio first, then divide by his actual months (8, not 12).",
        ),
    pyq(RY, 4, "q-pt-late",
        'A started some business with ₹26,000. After 3 months B joined him with ₹16,000. After some more time C joined them with ₹25,000. At the end of the year, out of a total profit of ₹15,453, C gets ₹3,825 as his share. How many months after B joined did C join the business?',
        ['3', '4', '5', 'None of these'], "a",
        ["Let C join t months after B. Capital-months: A = 26,000×12, B = 16,000×9, C = 25,000×(9 − t) (in thousands: 312, 144, 25(9−t)).", "C's share fraction 3,825/15,453 simplifies to 25/101, so 25(9−t) ÷ (456 + 225 − 25t) = 25/101.", 'Solving gives 101(9 − t) = 681 − 25t, so 76t = 228 and t = 3.'],
        lambda: 3, 3, 0, tech=['ratio-parts', 'back-substitute'], concepts=3, heavy=True,
        optvals=[opt_val(o) for o in ['3', '4', '5', 'None of these']],
        trick="Reduce C's share fraction (3,825/15,453 = 25/101) first, then solve the single linear equation in t.",
        wrong={'c': mistake('A plausible-looking guess that does not satisfy the reduced fraction 25/101.', 5, 0)}),
    pyq(RY, 10, "q-pt-late",
        'A started a business with ₹45,000. B joined afterward with ₹30,000. If the profit at the end of the year was divided in the ratio 2 : 1, then how long after A started did B join?',
        ['1 month', '2 months', '3 months', '4 months'], "c",
        ["A's capital-months = 45,000×12 = 5,40,000.", 'With ratio A : B = 2 : 1, B’s capital-months must be 5,40,000 ÷ 2 = 2,70,000, so 30,000 × (12 − m) = 2,70,000.', '12 − m = 9, so m = 3.'],
        lambda: 12 - F(45000 * 12, 2 * 30000), 3, 0, tech=['ratio-parts'], concepts=2,
        trick="Get B's capital-months from the ratio first (half of A's here), then solve for his months in business."),
    pyq(RY, 21, "q-pt-late",
        'A invested an amount of ₹25,000 and started a business. B joined him after one year with an amount of ₹30,000. After two years from starting the business, they earned a profit of ₹46,000. What will be B’s share in the profit?',
        ['₹14,000', '₹12,000', '₹17,250', '₹20,000'], "c",
        ['Over the full two years (24 months), A invests for all 24 months and B joins after 12 months, so B invests for 12 months.', 'Capital-months: A = 25,000×24 = 6,00,000; B = 30,000×12 = 3,60,000 — ratio 5 : 3.', "B's share = 3/8 × 46,000 = ₹17,250."],
        lambda: F(3 * 46000, 8), 17250, 0, tech=['ratio-parts'], concepts=2,
        trick='The same capital-months method still works over a multi-year span — just use total months, not 12.',
        ),
    pyq(RY, 22, "q-pt-late",
        'Mr. A opened a workshop investing ₹40,000. He invested an additional ₹10,000 every year. After two years his student B joined him with an amount of ₹85,000. Thereafter B did not invest any additional amount. On completion of four years from the opening of the workshop, they earned an amount of ₹1,95,000. What will be A’s share in the earning?',
        ['₹85,000', '₹1,10,000', '₹1,35,000', '₹95,000'], "b",
        ["A's capital in each of the 4 years: ₹40,000, ₹50,000, ₹60,000, ₹70,000 — capital-years total 40+50+60+70 = 220 (in thousands).", "B invests a flat ₹85,000 for the last 2 years: capital-years = 85×2 = 170 (in thousands).", "A's share = 220/390 × 1,95,000 = ₹1,10,000."],
        lambda: F((40 + 50 + 60 + 70) * 195000, (40 + 50 + 60 + 70) + 85 * 2), 110000, 0, tech=['ratio-parts'], concepts=3, heavy=True,
        trick="Treat each year's capital as its own 'capital-months' block (a full year each) and add them up, exactly like a mid-year change in capital.",
        wrong={'a': mistake("Gave B's capital-year total's matching share (170/390 × 1,95,000) instead of A's.", 85000, 0)}),

    # --- q-pt-working (existing): a working partner's commission comes off the top ---
    pyq(RY, 6, "q-pt-working",
        'A started a business with ₹52,000 and after 4 months B joined him with ₹39,000. At the end of the year, out of the total profit, B received a total of ₹20,000 including 25% of the profit as commission for managing the business. What amount did A receive?',
        ['₹20,000', '₹10,000', '₹15,000', 'None of these'], "a",
        ["Capital-months: A = 52,000×12, B = 39,000×8 — ratio 2 : 1.", "Let the total profit be P. Commission = 0.25P, balance = 0.75P, and B (1 of 3 parts) gets 0.25P + (1/3)(0.75P) = 0.5P = ₹20,000, so P = ₹40,000.", "A's amount is his 2/3 share of the balance: 2/3 × 0.75 × 40,000 = ₹20,000."],
        lambda: F(2, 3) * F(3, 4) * 40000, 20000, 0, tech=['fraction-percent', 'back-substitute'], concepts=3, heavy=True,
        optvals=[opt_val(o) for o in ['₹20,000', '₹10,000', '₹15,000', 'None of these']],
        trick="Use B's known total to find the overall profit first, then take A's ratio share of the balance.",
        wrong={'b': mistake("Gave B's balance share (1/3 of 30,000) instead of A's.", 10000, 0)}),
    pyq(RY, 7, "q-pt-working",
        'A working partner gets 20% as his commission of the profit after his commission is paid. If the working partner’s commission is ₹8,000, then what is the total profit in the business?',
        ['₹47,000', '₹45,000', '₹48,000', 'None of these'], "c",
        ['The commission is 20% of what is left AFTER the commission itself is removed, so C = 0.2 × (P − C).', 'That gives 1.2C = 0.2P, so C = P/6, i.e. P = 6C.', 'P = 6 × 8,000 = ₹48,000.'],
        lambda: 6 * 8000, 48000, 0, tech=['fraction-percent'], concepts=2,
        optvals=[opt_val(o) for o in ['₹47,000', '₹45,000', '₹48,000', 'None of these']],
        trick='A commission defined on the profit "after" itself is removed needs its own small equation — it is not simply 20% of the total profit.',
        wrong={'a': mistake('Treated the commission as 20% of the total profit directly (8,000 ÷ 0.2) instead of solving the self-referential relation.', 40000, 7000)}),

    # --- q-pt-pasture (existing): rent/pasture split by animals × months ---
    pyq(RY, 12, "q-pt-pasture",
        "Four milkmen rented a pasture. M put 16 cows to graze for 3 months, N grazed cows for 4 months, O grazed 18 cows for 6 months, and P grazed 42 cows for 2 months. If M's share of the rent is ₹2,400, the rent paid by O is:",
        ['₹3200', '₹4200', '₹4000', '₹5400'], "d",
        ["Rent splits in proportion to cows × months. M's share (16×3 = 48 cow-months) is ₹2,400, so one cow-month costs 2,400 ÷ 48 = ₹50.", "O's cow-months = 18×6 = 108, so O pays 108 × 50 = ₹5,400."],
        lambda: F(2400, 48) * 108, 5400, 0, tech=['ratio-parts'], concepts=1,
        trick="Find the rent per cow-month from M's own figures first, then apply it to O's cow-months — N and P's numbers are not even needed."),

    # --- q-pt-find-time (new): the profit ratio is given, solve for an unknown time ---
    pyq(RY, 11, "q-pt-find-time",
        'X and Y are partners in a business. They invest in the ratio 5 : 6. At the end of 8 months, X withdraws his capital. If they receive profits in the ratio 5 : 9, find how long Y’s investment was used.',
        ['12 months', '10 months', '15 months', '14 months'], "a",
        ["X's capital-months = 5×8 = 40 (units). Let Y's capital be used for T months, giving capital-months 6T.", "The profit ratio 5 : 9 means 40 ÷ 6T = 5 ÷ 9, so 360 = 30T.", "T = 12 months."],
        lambda: F(40 * 9, 5 * 6), 12, 0, tech=['ratio-parts', 'back-substitute'], concepts=2,
        trick="Write X's fixed capital-months, then solve for Y's unknown time from the given profit ratio."),
    pyq(RY, 23, "q-pt-find-time",
        'X and Y enter into a partnership with their capitals in the ratio 7 : 9. At the end of 8 months, X withdraws his capital. If they receive the profits in the ratio 8 : 9, find how long Y’s capital was used.',
        ['4 months', '6 months', '7 months', '8 months'], "c",
        ["X's capital-months = 7×8 = 56. Let Y's capital be used for T months, giving capital-months 9T.", "The profit ratio 8 : 9 means 56 ÷ 9T = 8 ÷ 9, so 504 = 72T.", "T = 7 months."],
        lambda: F(56 * 9, 8 * 9), 7, 0, tech=['ratio-parts', 'back-substitute'], concepts=2,
        trick="Same method as any early-withdrawal partner question, just solved backwards for the time instead of the share."),
    pyq(RY, 17, "q-pt-find-time",
        'A starts a business with ₹21,000, and later B joins him with ₹36,000. After how many months did B join if the profit at the end of the year is distributed in equal proportions?',
        ['5', '7', '6', '9'], "a",
        ["Equal profit shares means equal capital-months: A's = 21,000×12 = 2,52,000.", "B's capital-months must also be 2,52,000, so 36,000 × (12 − m) = 2,52,000.", '12 − m = 7, so m = 5.'],
        lambda: 12 - F(21000 * 12, 36000), 5, 0, tech=['ratio-parts', 'back-substitute'], concepts=2,
        trick='Equal profit shares (1 : 1) means equal capital-months — set them equal and solve for the unknown month.'),

    # --- q-pt-split-rule (new): part of the profit is removed (tax, or an equal share) before the ratio split ---
    pyq(RY, 8, "q-pt-split-rule",
        'Rakesh Yadav Reader publication makes a profit of ₹9,00,000, 20% of which is paid as taxes. If the rest is divided among the partners P, Q and R in the ratio 1 : 1½ : 2, then the shares of P, Q and R respectively are:',
        ['₹2,40,000; ₹3,20,000; ₹1,60,000', '₹3,20,000; ₹2,40,000; ₹1,60,000', '₹1,60,000; ₹3,20,000; ₹2,40,000', '₹1,60,000; ₹2,40,000; ₹3,20,000'], "d",
        ['After tax, the amount left to share is 80% of 9,00,000 = ₹7,20,000.', 'The ratio 1 : 1½ : 2 is the same as 2 : 3 : 4 (9 parts).', 'P = 2/9 × 7,20,000 = ₹1,60,000; Q = 3/9 × 7,20,000 = ₹2,40,000; R = 4/9 × 7,20,000 = ₹3,20,000.'],
        lambda: 1, 1, 0, tech=['fraction-percent', 'ratio-parts'], optvals=[0, 0, 0, 1], concepts=2,
        trick='Remove the tax first, then split only what remains in the given ratio.'),
    pyq(RY, 25, "q-pt-split-rule",
        'Two partners invest ₹1,25,000 and ₹85,000 respectively in a business and agree that 60% of the profit should be divided equally between them, and the remaining profit is to be divided in the ratio of their capitals. If one partner gets ₹300 more than the other, find the total profit made in the business.',
        ['₹3739.50', '₹3937.50', '₹3749.50', '₹3947.50'], "b",
        ['The equal 60% share is the same for both, so the whole ₹300 difference comes from the remaining 40%, split 1,25,000 : 85,000 = 25 : 17 (42 parts).', "The gap between the two ratio shares is (25 − 17)/42 of 40% of the profit, i.e. 8/105 of the profit.", 'Setting 8P/105 = 300 gives P = ₹3,937.50.'],
        lambda: F(300 * 105, 8), 3937.5, 1e-9, tech=['fraction-percent', 'ratio-parts'], concepts=3, heavy=True,
        trick='Only the ratio-split 40% creates any difference between the two partners — work the ₹300 gap back from that portion alone.'),
]
